const axios = require('axios');
const fs = require('fs');
const path = require('path');
const file = path.resolve(__rootdir, 'trivia_game.json');
let state = { chats: {}, scores: {} };
try { if(fs.existsSync(file)) state = JSON.parse(fs.readFileSync(file, 'utf8')); } catch(e) {}

const arg = argumentName ? argumentName.trim().toLowerCase() : '';
const chat = remoteJid;
const user = msg.key?.participant || remoteJid;
const username = msg.pushName || user.split('@')[0];

if (arg === 'lb' || arg === 'leaderboard') {
    let scores = Object.entries(state.scores).sort((a,b)=>b[1]-a[1]).slice(0, 10);
    if (!scores.length) return sendTrackedMessage(sock, chat, "No scores yet!");
    let text = "🏆 *TRIVIA LEADERBOARD* 🏆\n\n";
    scores.forEach((s, i) => text += `${i+1}. @${s[0].split('@')[0]} - ${s[1]} pts\n`);
    return sock.sendMessage(chat, { text, mentions: scores.map(s => s[0]) });
}

if (!arg || arg === 'start') {
    if (state.chats[chat]) return sendTrackedMessage(sock, chat, "A game is already running! Answer using !trivia <A|B|C|D>");
    try {
        const res = await axios.get('https://opentdb.com/api.php?amount=1&type=multiple');
        const q = res.data.results[0];
        let options = [...q.incorrect_answers, q.correct_answer].sort(() => Math.random() - 0.5);
        state.chats[chat] = {
            q: q.question.replace(/&quot;/g, '"').replace(/&#039;/g, "'").replace(/&amp;/g, '&').replace(/&Ouml;/g, 'Ö').replace(/&ldquo;/g, '"').replace(/&rdquo;/g, '"'),
            ans: String.fromCharCode(65 + options.indexOf(q.correct_answer)),
            opts: options
        };
        fs.writeFileSync(file, JSON.stringify(state, null, 2));
        let text = `🎯 *TRIVIA TIME* 🎯\n\n*Difficulty:* ${q.difficulty}\n*Category:* ${q.category}\n\n*${state.chats[chat].q}*\n\n`;
        options.forEach((o, i) => {
            const opt = o.replace(/&quot;/g, '"').replace(/&#039;/g, "'").replace(/&amp;/g, '&').replace(/&Ouml;/g, 'Ö').replace(/&ldquo;/g, '"').replace(/&rdquo;/g, '"');
            text += `*${String.fromCharCode(65 + i)}.* ${opt}\n`;
        });
        text += "\n_Reply with !trivia <A|B|C|D>_";
        return sendTrackedMessage(sock, chat, text);
    } catch (e) {
        return sendTrackedMessage(sock, chat, "❌ Failed to fetch question. Try again later.");
    }
}

if (state.chats[chat]) {
    const active = state.chats[chat];
    if (['a','b','c','d'].includes(arg)) {
        if (arg.toUpperCase() === active.ans) {
            state.scores[user] = (state.scores[user] || 0) + 1;
            delete state.chats[chat];
            fs.writeFileSync(file, JSON.stringify(state, null, 2));
            return sock.sendMessage(chat, { text: `✅ *Correct, @${user.split('@')[0]}!* The answer was ${active.ans}.\n\nYou now have ${state.scores[user]} points.`, mentions: [user] });
        } else {
            return sendTrackedMessage(sock, chat, `❌ Incorrect! Try again.`);
        }
    } else {
        return sendTrackedMessage(sock, chat, `⚠️ Active trivia running! Use !trivia <A|B|C|D> or !trivia lb`);
    }
} else {
    return sendTrackedMessage(sock, chat, `Type !trivia start to play!`);
}

