let state = { chats: {}, scores: {} };
try { if(fs.existsSync(file)) state = JSON.parse(fs.readFileSync(file, 'utf8')); } catch(e) {}

const arg = argumentName ? argumentName.trim().toLowerCase() : '';
const chat = remoteJid;
const user = msg.key?.participant || remoteJid;

if (arg === 'lb' || arg === 'leaderboard') {
    let scores = Object.entries(state.scores).sort((a,b)=>b[1]-a[1]).slice(0, 10);
    if (!scores.length) return sendTrackedMessage(sock, chat, "No scores yet!");
    let text = "🏆 *GUESS LEADERBOARD* 🏆\n\n";
    scores.forEach((s, i) => text += `${i+1}. @${s[0].split('@')[0]} - ${s[1]} wins\n`);
    return sock.sendMessage(chat, { text, mentions: scores.map(s => s[0]) });
}

if (!arg || arg === 'start') {
    if (state.chats[chat]) return sendTrackedMessage(sock, chat, `A game is running! Guess the number between 1 and 100! (e.g. !guess 50)`);
    state.chats[chat] = {
        num: Math.floor(Math.random() * 100) + 1,
        attempts: 0
    };
    fs.writeFileSync(file, JSON.stringify(state, null, 2));
    return sendTrackedMessage(sock, chat, `🎲 *GUESS THE NUMBER* 🎲\n\nI'm thinking of a number between 1 and 100.\n\n_Reply with !guess <number>_`);
}

if (state.chats[chat]) {
    const guess = parseInt(arg);
    if (isNaN(guess)) return sendTrackedMessage(sock, chat, "Please guess a valid number!");

    state.chats[chat].attempts++;
    const target = state.chats[chat].num;

    if (guess === target) {
        state.scores[user] = (state.scores[user] || 0) + 1;
        const attempts = state.chats[chat].attempts;
        delete state.chats[chat];
        fs.writeFileSync(file, JSON.stringify(state, null, 2));
        return sock.sendMessage(chat, { text: `🎉 *BINGO, @${user.split('@')[0]}!*\n\nYou guessed the number ${target} in ${attempts} attempts!\nTotal Wins: ${state.scores[user]}`, mentions: [user] });
    } else if (guess < target) {
        fs.writeFileSync(file, JSON.stringify(state, null, 2));
        return sendTrackedMessage(sock, chat, `🔼 Higher! (Attempt ${state.chats[chat].attempts})`);
    } else {
        fs.writeFileSync(file, JSON.stringify(state, null, 2));
        return sendTrackedMessage(sock, chat, `🔽 Lower! (Attempt ${state.chats[chat].attempts})`);
    }
} else {
    return sendTrackedMessage(sock, chat, `Type !guess start to play!`);
}

