const arg = argumentName ? argumentName.trim().toLowerCase() : '';
const chat = remoteJid;
const user = msg.key?.participant || remoteJid;

if (arg === 'lb' || arg === 'leaderboard') {
    let scores = Object.entries(state.scores).sort((a,b)=>b[1]-a[1]).slice(0, 10);
    if (!scores.length) return sendTrackedMessage(sock, chat, "No scores yet!");
    let text = "🏆 *MATH LEADERBOARD* 🏆\n\n";
    scores.forEach((s, i) => text += `${i+1}. @${s[0].split('@')[0]} - ${s[1]} pts\n`);
    return sock.sendMessage(chat, { text, mentions: scores.map(s => s[0]) });
}

if (!arg || arg === 'start') {
    if (state.chats[chat]) return sendTrackedMessage(sock, chat, "Finish the current math problem first! (Reply with !math <number>)");
    const ops = ['+', '-', '*'];
    const op = ops[Math.floor(Math.random() * ops.length)];
    let a = Math.floor(Math.random() * 50) + 1;
    let b = Math.floor(Math.random() * 50) + 1;
    let ans = 0;
    if (op === '*') {
        a = Math.floor(Math.random() * 12) + 2;
        b = Math.floor(Math.random() * 12) + 2;
        ans = a * b;
    } else if (op === '+') {
        ans = a + b;
    } else {
        if (a < b) { let temp = a; a = b; b = temp; }
        ans = a - b;
    }

    state.chats[chat] = { q: `${a} ${op} ${b}`, ans: ans };
    fs.writeFileSync(file, JSON.stringify(state, null, 2));
    return sendTrackedMessage(sock, chat, `🧠 *MATH CHALLENGE* 🧠\n\nSolve this:\n*${a} ${op} ${b} = ?*\n\n_Reply with !math <answer>_`);
}

if (state.chats[chat]) {
    const guess = parseInt(arg);
    if (isNaN(guess)) return sendTrackedMessage(sock, chat, "Provide a valid number!");

    if (guess === state.chats[chat].ans) {
        state.scores[user] = (state.scores[user] || 0) + 1;
        delete state.chats[chat];
        fs.writeFileSync(file, JSON.stringify(state, null, 2));
        return sock.sendMessage(chat, { text: `✅ *Brilliant, @${user.split('@')[0]}!*\nCorrect answer was ${guess}.\nPoints: ${state.scores[user]}`, mentions: [user] });
    } else {
        return sendTrackedMessage(sock, chat, `❌ Incorrect! Keep trying.`);
    }
} else {
    return sendTrackedMessage(sock, chat, `Type !math start to play!`);
}

